package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.workbench.proxy.WorkbenchServlet;
import org.junit.jupiter.api.Test;

class WorkbenchSessionStateSecurityTest {

	@Test
	void reusesOnlyMatchingServerAndCredentialMarker() {
		WorkbenchSessionState state = new WorkbenchSessionState();
		RecordingServlet original = new RecordingServlet();

		try (WorkbenchSessionState.Lease first = state.acquire("https://example.org/server", "alice", () -> original);
				WorkbenchSessionState.Lease second = state.acquire("https://example.org/server", "alice",
						RecordingServlet::new)) {
			assertThat(first.servlet()).isSameAs(original);
			assertThat(second.servlet()).isSameAs(original);
		}

		RecordingServlet replacement = new RecordingServlet();
		try (WorkbenchSessionState.Lease lease = state.acquire("https://example.org/server", "bob",
				() -> replacement)) {
			assertThat(lease.servlet()).isSameAs(replacement);
		}
		assertThat(original.destroyCount).isEqualTo(1);
	}

	@Test
	void independentStatesNeverShareCredentialBearingServlets() {
		WorkbenchSessionState aliceState = new WorkbenchSessionState();
		WorkbenchSessionState bobState = new WorkbenchSessionState();
		RecordingServlet alice = new RecordingServlet();
		RecordingServlet bob = new RecordingServlet();

		try (WorkbenchSessionState.Lease aliceLease = aliceState.acquire("https://example.org/server", "alice",
				() -> alice);
				WorkbenchSessionState.Lease bobLease = bobState.acquire("https://example.org/server", "bob",
						() -> bob)) {
			assertThat(aliceLease.servlet()).isSameAs(alice);
			assertThat(bobLease.servlet()).isSameAs(bob);
			assertThat(aliceLease.servlet()).isNotSameAs(bobLease.servlet());
		}
	}

	@Test
	void sessionExpiryDestroysAllOwnedServletsAndClosesState() {
		WorkbenchSessionState state = new WorkbenchSessionState();
		RecordingServlet first = new RecordingServlet();
		RecordingServlet second = new RecordingServlet();
		WorkbenchSessionState.Lease firstLease = state.acquire("https://one.example/server", "alice", () -> first);
		try (WorkbenchSessionState.Lease ignored = state.acquire("https://two.example/server", "alice", () -> second)) {
			// Keep only the first servlet in use while the state closes.
		}

		state.close();
		state.close();

		assertThat(first.destroyCount).isZero();
		assertThat(second.destroyCount).isEqualTo(1);
		firstLease.close();
		assertThat(first.destroyCount).isEqualTo(1);
		assertThatThrownBy(() -> state.acquire("https://one.example/server", "alice", RecordingServlet::new))
				.isInstanceOf(IllegalStateException.class);
	}

	@Test
	void credentialReplacementWaitsForInFlightRequestsBeforeDestroyingOldServlet() {
		WorkbenchSessionState state = new WorkbenchSessionState();
		RecordingServlet alice = new RecordingServlet();
		RecordingServlet bob = new RecordingServlet();
		WorkbenchSessionState.Lease aliceLease = state.acquire("https://example.org/server", "alice", () -> alice);

		try (WorkbenchSessionState.Lease bobLease = state.acquire("https://example.org/server", "bob", () -> bob)) {
			assertThat(bobLease.servlet()).isSameAs(bob);
			assertThat(alice.destroyCount).isZero();
		}

		aliceLease.close();
		assertThat(alice.destroyCount).isEqualTo(1);
	}

	@Test
	void concurrentRequestsCreateOneServletPerSessionKey() throws Exception {
		WorkbenchSessionState state = new WorkbenchSessionState();
		CountDownLatch factoryEntered = new CountDownLatch(1);
		CountDownLatch releaseFactory = new CountDownLatch(1);
		RecordingServlet created = new RecordingServlet();
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			Future<WorkbenchServlet> first = executor.submit(() -> {
				try (WorkbenchSessionState.Lease lease = state.acquire("https://example.org/server", "alice", () -> {
					factoryEntered.countDown();
					try {
						releaseFactory.await(5, TimeUnit.SECONDS);
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new IllegalStateException(e);
					}
					return created;
				})) {
					return lease.servlet();
				}
			});
			assertThat(factoryEntered.await(5, TimeUnit.SECONDS)).isTrue();
			Future<WorkbenchServlet> second = executor.submit(() -> {
				try (WorkbenchSessionState.Lease lease = state.acquire(
						"https://example.org/server", "alice", RecordingServlet::new)) {
					return lease.servlet();
				}
			});

			releaseFactory.countDown();

			assertThat(first.get(5, TimeUnit.SECONDS)).isSameAs(created);
			assertThat(second.get(5, TimeUnit.SECONDS)).isSameAs(created);
		} finally {
			executor.shutdownNow();
		}
	}

	private static final class RecordingServlet extends WorkbenchServlet {
		private int destroyCount;

		@Override
		public void destroy() {
			destroyCount++;
		}
	}
}
